'use client';

import { directionOf, formatMoney, formatPercent } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument } from '../../types';
import { cn } from '../../utils';
import { Delta } from './delta';
import { Stat } from './stat';

export interface Account {
  equity: number;
  /** Cash available to open new positions. */
  buyingPower: number;
  /** Equity at the previous close, for the day figure. */
  previousEquity?: number;
  cash?: number;
  /** Margin currently posted. */
  marginUsed?: number;
  /** Total margin the account is allowed. */
  marginAvailable?: number;
  realizedPnl?: number;
  unrealizedPnl?: number;
}

export interface AccountSummaryProps {
  account: Account;
  instrument?: Partial<Instrument>;
  /** Stacked for a sidebar, inline for a header strip. */
  layout?: 'grid' | 'inline';
  className?: string;
}

/** Account health at a glance: equity, day P&L, buying power, margin. */
export function AccountSummary({
  account,
  instrument,
  layout = 'grid',
  className,
}: AccountSummaryProps) {
  const inst = useInstrument(instrument);
  const {
    equity,
    buyingPower,
    previousEquity,
    cash,
    marginUsed,
    marginAvailable,
    realizedPnl,
    unrealizedPnl,
  } = account;

  const dayPnl = previousEquity !== undefined ? equity - previousEquity : undefined;
  const dayPct = previousEquity ? dayPnl! / previousEquity : undefined;
  const marginPct =
    marginUsed !== undefined && marginAvailable ? marginUsed / marginAvailable : undefined;

  return (
    <div
      className={cn(
        layout === 'grid'
          ? 'grid grid-cols-2 gap-x-6 gap-y-4 p-3'
          : 'flex flex-wrap items-center gap-x-8 gap-y-3 p-3',
        className,
      )}
    >
      <Stat
        size="lg"
        label="Equity"
        value={formatMoney(equity, inst.currency)}
        hint={
          dayPnl !== undefined ? <Delta value={dayPnl} percent={dayPct} icon={false} /> : undefined
        }
      />
      <Stat label="Buying power" value={formatMoney(buyingPower, inst.currency)} />

      {unrealizedPnl !== undefined && (
        <Stat
          label="Unrealized"
          value={formatMoney(unrealizedPnl, inst.currency)}
          direction={directionOf(unrealizedPnl)}
        />
      )}
      {realizedPnl !== undefined && (
        <Stat
          label="Realized"
          value={formatMoney(realizedPnl, inst.currency)}
          direction={directionOf(realizedPnl)}
        />
      )}
      {cash !== undefined && <Stat label="Cash" value={formatMoney(cash, inst.currency)} />}

      {marginPct !== undefined && (
        <div className="col-span-2 flex flex-col gap-1.5">
          <div className="flex items-baseline justify-between">
            <span className="text-muted-foreground text-[10px] font-medium tracking-wider uppercase">
              Margin used
            </span>
            <span className="font-mono text-[11px] tabular-nums">
              {formatMoney(marginUsed!, inst.currency)}{' '}
              <span className="text-muted-foreground">
                / {formatMoney(marginAvailable!, inst.currency)}
              </span>
            </span>
          </div>
          <MarginBar value={marginPct} />
        </div>
      )}
    </div>
  );
}

export interface MarginBarProps {
  /** Utilisation as a ratio of the limit. */
  value: number;
  /** Utilisation above this is a warning. */
  warnAt?: number;
  /** Utilisation above this is a danger. */
  dangerAt?: number;
  className?: string;
}

/**
 * Margin utilisation.
 *
 * Banded rather than a smooth gradient, and the thresholds are marked on the
 * track: the number that matters is not "how full" but "how close to the level
 * where you get called", and a gradient hides exactly that boundary.
 */
export function MarginBar({ value, warnAt = 0.6, dangerAt = 0.85, className }: MarginBarProps) {
  const pct = Math.max(0, Math.min(1, value));
  const tone = pct >= dangerAt ? 'bg-down' : pct >= warnAt ? 'bg-warn' : 'bg-up';

  return (
    <div
      className={cn('relative h-1.5 w-full overflow-hidden rounded-full', 'bg-secondary', className)}
      role="meter"
      aria-valuenow={Math.round(pct * 100)}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label="Margin utilisation"
    >
      <div
        className={cn('h-full rounded-full transition-[width] duration-300', tone)}
        style={{ width: `${pct * 100}%` }}
      />
      {[warnAt, dangerAt].map((mark) => (
        <span
          key={mark}
          aria-hidden="true"
          className="bg-background/80 absolute inset-y-0 w-px"
          style={{ left: `${mark * 100}%` }}
        />
      ))}
    </div>
  );
}

export interface RiskMeterProps {
  /** 0–1. Anything you want scored: margin, concentration, leverage. */
  value: number;
  label?: string;
  warnAt?: number;
  dangerAt?: number;
  className?: string;
}

/** A labelled risk reading with its level named, not only coloured. */
export function RiskMeter({
  value,
  label = 'Risk',
  warnAt = 0.6,
  dangerAt = 0.85,
  className,
}: RiskMeterProps) {
  const pct = Math.max(0, Math.min(1, value));
  const level = pct >= dangerAt ? 'High' : pct >= warnAt ? 'Elevated' : 'Normal';
  const tone = pct >= dangerAt ? 'text-down' : pct >= warnAt ? 'text-foreground' : 'text-up';

  return (
    <div className={cn('flex flex-col gap-1.5', className)}>
      <div className="flex items-baseline justify-between">
        <span className="text-muted-foreground text-[10px] font-medium tracking-wider uppercase">
          {label}
        </span>
        <span className={cn('font-mono text-[11px] font-semibold tabular-nums', tone)}>
          {formatPercent(pct, 0, false)} · {level}
        </span>
      </div>
      <MarginBar value={pct} warnAt={warnAt} dangerAt={dangerAt} />
    </div>
  );
}

'use client';

import { TrendingDownIcon, TrendingUpIcon } from 'lucide-react';
import { directionOf, formatPercent, formatSigned } from '../../format';
import { cn } from '../../utils';
import { Badge } from '../ui/badge';

export interface DeltaProps {
  /** Absolute change. Omit to show the percentage alone. */
  value?: number;
  /** Change as a ratio (0.0421 renders as +4.21%). */
  percent?: number;
  precision?: number;
  /** Boxed badge instead of bare text. */
  pill?: boolean;
  /** Prefix with a trend icon. */
  icon?: boolean;
  className?: string;
}

/**
 * The change indicator.
 *
 * Direction is carried three ways at once - color, an icon, and an explicit
 * sign. Color alone fails a colorblind reader; in a grayscale screenshot or a
 * printed risk report it fails everyone.
 */
export function Delta({
  value,
  percent,
  precision = 2,
  pill = false,
  icon = true,
  className,
}: DeltaProps) {
  const basis = value ?? percent ?? 0;
  const direction = directionOf(basis);

  const parts: string[] = [];
  if (value !== undefined) parts.push(formatSigned(value, precision));
  if (percent !== undefined) {
    parts.push(
      value !== undefined
        ? `(${formatPercent(percent, precision, false)})`
        : formatPercent(percent, precision),
    );
  }

  const Icon =
    direction === 'up' ? TrendingUpIcon : direction === 'down' ? TrendingDownIcon : null;
  const tone = direction === 'up' ? 'text-up' : direction === 'down' ? 'text-down' : 'text-flat';

  const body = (
    <>
      {icon && Icon && <Icon className="size-3 shrink-0" aria-hidden="true" />}
      <span className="sr-only">
        {direction === 'up' ? 'up' : direction === 'down' ? 'down' : 'unchanged'}{' '}
      </span>
      {parts.join(' ')}
    </>
  );

  if (pill) {
    return (
      <Badge variant={direction} className={cn('font-mono tabular-nums', className)}>
        {body}
      </Badge>
    );
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 font-mono text-xs font-semibold tabular-nums whitespace-nowrap',
        tone,
        className,
      )}
    >
      {body}
    </span>
  );
}

'use client';

import type { ReactNode } from 'react';
import type { Direction } from '../../types';
import { cn } from '../../utils';

export interface StatProps {
  label: ReactNode;
  value: ReactNode;
  /** Small trailing element - a Delta, a unit, a badge. */
  hint?: ReactNode;
  /** Color the value by direction. */
  direction?: Direction;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

const VALUE_SIZE = { sm: 'text-sm', md: 'text-base', lg: 'text-2xl' } as const;

/** A labelled figure. The unit of a stat row or a KPI strip. */
export function Stat({ label, value, hint, direction, size = 'md', className }: StatProps) {
  return (
    <div className={cn('flex min-w-0 flex-col gap-0.5', className)}>
      <span className="text-muted-foreground text-[10px] font-medium tracking-wider whitespace-nowrap uppercase">
        {label}
      </span>
      <span className="flex items-baseline gap-1.5">
        <span
          className={cn(
            'font-mono leading-tight font-semibold tabular-nums',
            VALUE_SIZE[size],
            direction === 'up' && 'text-up',
            direction === 'down' && 'text-down',
            direction === 'flat' && 'text-flat',
          )}
        >
          {value}
        </span>
        {hint}
      </span>
    </div>
  );
}

'use client';

import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-md border px-1.5 py-0.5 text-[10px] font-semibold tracking-wide whitespace-nowrap [&>svg]:pointer-events-none [&>svg:not([class*='size-'])]:size-3",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground border-transparent',
        secondary: 'bg-secondary text-secondary-foreground border-transparent',
        outline: 'text-foreground',
        up: 'bg-up-muted text-up border-transparent',
        down: 'bg-down-muted text-down border-transparent',
        flat: 'bg-muted text-flat border-transparent',
      },
    },
    defaultVariants: { variant: 'default' },
  },
);

function Badge({
  className,
  variant,
  asChild = false,
  ...props
}: ComponentProps<'span'> & VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'span';
  return (
    <Comp data-slot="badge" className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

'use client';

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { TooltipProvider } from '../components/ui/tooltip';
import type { Instrument } from '../types';
import { cn } from '../utils';

export type ThemeName = 'dark' | 'light';
export type DirectionPalette = 'classic' | 'colorblind';

export interface TradingTheme {
  theme: ThemeName;
  /** `classic` is green/red; `colorblind` is blue/amber. */
  palette: DirectionPalette;
  /** Formatting defaults for components not given their own instrument. */
  instrument: Instrument;
}

export const defaultInstrument: Instrument = {
  symbol: '',
  pricePrecision: 2,
  tickSize: 0.01,
  sizePrecision: 0,
  currency: '$',
};

const ThemeContext = createContext<TradingTheme>({
  theme: 'dark',
  palette: 'classic',
  instrument: defaultInstrument,
});

export function useTradingTheme(): TradingTheme {
  return useContext(ThemeContext);
}

/**
 * Resolves the instrument a component formats with: its own prop wins, then
 * the provider's, then the library default.
 */
export function useInstrument(override?: Partial<Instrument>): Instrument {
  const { instrument } = useTradingTheme();
  return useMemo(
    () => (override ? { ...instrument, ...override } : instrument),
    [instrument, override],
  );
}

export interface TradingProviderProps {
  children: ReactNode;
  theme?: ThemeName;
  palette?: DirectionPalette;
  instrument?: Partial<Instrument>;
  /** Token overrides, e.g. `{ '--primary': '#ff8a00' }`. */
  tokens?: Record<string, string>;
  /**
   * Skip the wrapper element and inherit whatever theme the host already
   * applies. Use this inside an existing shadcn app that owns `.dark` itself.
   */
  inherit?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Scopes theme, direction palette and instrument defaults to a subtree.
 *
 * Deliberately not a global stylesheet switch: two providers can coexist, so a
 * light-themed report can sit inside a dark terminal. Also mounts a single
 * Radix TooltipProvider so every tooltip in the tree shares one delay timer.
 */
export function TradingProvider({
  children,
  theme = 'dark',
  palette = 'classic',
  instrument,
  tokens,
  inherit = false,
  className,
  style,
}: TradingProviderProps) {
  const value = useMemo<TradingTheme>(
    () => ({ theme, palette, instrument: { ...defaultInstrument, ...instrument } }),
    [theme, palette, instrument],
  );

  const content = <TooltipProvider>{children}</TooltipProvider>;

  return (
    <ThemeContext.Provider value={value}>
      {inherit ? (
        content
      ) : (
        <div
          data-tu-theme={theme}
          data-tu-palette={palette}
          className={cn(
            'bg-background text-foreground',
            theme === 'dark' && 'dark',
            className,
          )}
          style={{ ...(tokens as CSSProperties | undefined), ...style }}
        >
          {content}
        </div>
      )}
    </ThemeContext.Provider>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared empty array, so a normalized-away prop keeps a stable identity and
 *  does not invalidate the `useMemo` that depends on it on every render. */
const EMPTY: readonly never[] = Object.freeze([]);

/**
 * Coerces a feed-supplied collection to something safe to iterate.
 *
 * A live feed is not a type system. Sockets drop fields, REST returns `null`
 * for "no rows yet", and a panel mounts before its first payload lands. None
 * of that should unmount the React tree — a component with nothing to show
 * renders its empty state instead. Returns a frozen shared array when the
 * input is unusable, so the identity stays stable across renders.
 */
export function toArray<T>(value: readonly T[] | null | undefined): readonly T[] {
  return Array.isArray(value) ? value : (EMPTY as readonly T[]);
}

/** `toArray` for both sides of a book, tolerating a missing snapshot entirely. */
export function toBook<T>(book: { bids?: readonly T[] | null; asks?: readonly T[] | null } | null | undefined) {
  return { bids: toArray(book?.bids), asks: toArray(book?.asks) };
}
